LOCK_STALE_SECONDS = int(os.environ.get("INTAKE_LOCK_STALE_SECONDS", "900"))


def _now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


class IntakeLock:
    """Exclusive lock file so two operators never merge into the current files at the same time."""
    def __init__(self, out_dir: str, timeout: float = 120, stale_after: float = LOCK_STALE_SECONDS):
        self.path, self.timeout, self.stale_after = os.path.join(out_dir, ".intake.lock"), timeout, stale_after

    def __enter__(self):
        deadline = time.time() + self.timeout
        while True:
            try:
                fd = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                with os.fdopen(fd, "w") as f:
                    f.write(json.dumps({"pid": os.getpid(), "acquired_at": _now()}))
                return self
            except FileExistsError:
                try:
                    if time.time() - os.path.getmtime(self.path) > self.stale_after:
                        os.remove(self.path)  # holder was interrupted; lock is stale
                        continue
                except FileNotFoundError:
                    continue
                if time.time() > deadline:
                    raise TimeoutError(f"intake lock is held by another run: {self.path}")
                time.sleep(1)

    def __exit__(self, *exc):
        try:
            os.remove(self.path)
        except FileNotFoundError:
            pass


def load_current(out_dir: str = OUTPUT_DIR) -> Dict[str, Dict[str, Any]]:
    path = os.path.join(out_dir, "extractions.jsonl")
    if not os.path.exists(path):
        return {}
    with open(path, encoding="utf-8") as f:
        return {r["document_id"]: r for r in (json.loads(line) for line in f if line.strip())}


def _archive(record: Dict[str, Any], out_dir: str) -> str:
    """Write one immutable attempt file under history/<document_id>/ and return its relative path."""
    doc_dir = os.path.join(out_dir, "history", record["document_id"])
    os.makedirs(doc_dir, exist_ok=True)
    stamp = re.sub(r"[^0-9]", "", (record.get("extracted_at") or _now())[:26])
    outcome = "ok" if record.get("error") is None else "error"
    name = (f"{stamp}-{record['source_sha256'][:12]}-{(record.get('settings_fingerprint') or 'none')[:12]}"
            f"-{outcome}-{random.randint(0, 999_999):06d}.json")
    _atomic_write(os.path.join(doc_dir, name), json.dumps(record, indent=2, ensure_ascii=False) + "\n")
    return os.path.relpath(os.path.join(doc_dir, name), out_dir)


def _success_pointer(rec: Dict[str, Any]) -> Dict[str, Any]:
    return {k: rec.get(k) for k in ("history_file", "source_sha256", "settings_fingerprint", "extracted_at", "response_source")}


def _reusable(old: Optional[Dict[str, Any]], sha: str) -> bool:
    return bool(old) and old.get("error") is None and old.get("extraction") is not None \
        and old.get("source_sha256") == sha and old.get("settings_fingerprint") == SETTINGS_FINGERPRINT


def run_intake(paths, out_dir: str = OUTPUT_DIR, responder=None, response_source: Optional[str] = None,
               force: bool = False, workers: Optional[int] = None) -> Dict[str, Any]:
    """Extract new/changed/failed documents, reuse unchanged ones, archive every attempt, write current files."""
    os.makedirs(out_dir, exist_ok=True)
    snapshot = load_current(out_dir)
    to_extract, reused = [], []
    for p in paths:
        with open(p, "rb") as f:
            sha = hashlib.sha256(f.read()).hexdigest()
        doc = os.path.basename(p)
        if not force and _reusable(snapshot.get(doc), sha):
            reused.append(doc)
        else:
            to_extract.append(p)

    new_records: Dict[str, Dict[str, Any]] = {}
    if to_extract:
        with ThreadPoolExecutor(max_workers=workers or int(os.environ.get("INTAKE_WORKERS", "4"))) as pool:
            futures = [pool.submit(extract_document, p, responder, response_source) for p in to_extract]
            for fut in as_completed(futures):
                rec = fut.result()
                new_records[rec["document_id"]] = rec

    with IntakeLock(out_dir):
        current = load_current(out_dir)  # re-read: another operator may have merged meanwhile
        for doc, rec in new_records.items():
            old = current.get(doc)
            if old and not old.get("history_file"):
                old["history_file"] = _archive(old, out_dir)  # archive pre-history records before superseding
            rec.update(route_record(rec))
            rec["history_file"] = _archive(rec, out_dir)
            if rec["error"] is None:
                rec["last_success"] = None
            elif old and old.get("error") is None:
                rec["last_success"] = _success_pointer(old)
            else:
                rec["last_success"] = old.get("last_success") if old else None
            current[doc] = rec
        for doc in reused:
            rec = current[doc]
            if not rec.get("history_file"):
                rec["history_file"] = _archive(rec, out_dir)
            rec.setdefault("last_success", None)
            rec.update(route_record(rec))  # picks up review-policy changes without a model call
        queue = write_deliverables(current, out_dir)

    failed = sorted(d for d, r in new_records.items() if r["error"])
    return {"extracted": sorted(new_records), "reused": sorted(reused), "failed": failed, "queue": queue}

